#!/usr/bin/env bun

// Writes hooks/vendor/markdown.js, the Markdown parser the mod links with,
// from scripts/markdown-entry.ts and the parser packages bun.lock pins, and
// hooks/vendor/markdown.licenses.txt, the license notice of every package
// bundled into it. A mod loads only its own files, so the parser ships as
// this one generated file. scripts/build-markdown.spec.ts fails when either
// committed file differs from a fresh build, so a dependency bump comes with
// its rebuilt files.
//
// Usage: bun scripts/build-markdown.ts [--check]
// --check writes nothing and exits 1 when a committed file is stale.
import { readdir } from "node:fs/promises";
import { join } from "node:path";
import { parseArgs } from "node:util";

const ROOT = join(import.meta.dir, "..");

export const OUTPUT_PATH = "hooks/vendor/markdown.js";

export const LICENSES_PATH = "hooks/vendor/markdown.licenses.txt";

/**
 * Licenses that let the bundle ship with their notice alone. Another
 * license fails the build, so a new dependency gets a person's look first.
 */
const ALLOWED_LICENSES = new Set([
  "MIT",
  "ISC",
  "BSD-2-Clause",
  "BSD-3-Clause",
]);

const BANNER = [
  "// Generated by scripts/build-markdown.ts from scripts/markdown-entry.ts.",
  "// Do not edit: run `bun run build:markdown`.",
  `// The bundled packages' license notices: ${LICENSES_PATH.replace("hooks/vendor/", "")}.`,
  "// @ts-nocheck",
  "/* eslint-disable */",
  "",
].join("\n");

export type Built = { bundle: string; licenses: string };

/**
 * Bundles the parser for the mod's environment, which has no DOM and no
 * Node: the node target picks the entity decoder that needs no `document`,
 * and NODE_ENV=production picks micromark's builds without the `debug`
 * logger, whose CommonJS would leave a `node:module` import behind.
 */
export async function buildMarkdown(): Promise<Built> {
  const result = await Bun.build({
    entrypoints: [join(ROOT, "scripts/markdown-entry.ts")],
    target: "node",
    format: "esm",
    define: { "process.env.NODE_ENV": JSON.stringify("production") },
    minify: true,
    metafile: true,
  });
  const [output] = result.outputs;
  if (!result.success || output === undefined) {
    throw new AggregateError(result.logs, "bun build failed");
  }

  const inputs = Object.keys(result.metafile?.inputs ?? {});

  return {
    bundle: BANNER + (await output.text()),
    licenses: await licensesOf(packagesIn(inputs)),
  };
}

/**
 * The package folders the bundle's inputs come from, sorted:
 * `node_modules/micromark/lib/x.js` is `node_modules/micromark`, and a
 * scoped package keeps its scope.
 */
export function packagesIn(inputs: readonly string[]): string[] {
  const packages = new Set<string>();
  for (const input of inputs) {
    const match = /^(node_modules\/(?:@[^/]+\/)?[^/]+)\//.exec(input);
    if (match?.[1] !== undefined) packages.add(match[1]);
  }

  return [...packages].toSorted();
}

/** Each package's name, version, license and license file, one after another. */
async function licensesOf(packages: readonly string[]): Promise<string> {
  const notices = await Promise.all(packages.map(noticeOf));

  return [
    "The license notices of the packages bundled into markdown.js.",
    ...notices,
  ].join(`\n${"-".repeat(72)}\n\n`);
}

/** One package's notice, or an error when its license needs a look. */
async function noticeOf(folder: string): Promise<string> {
  const manifest: unknown = await Bun.file(
    join(ROOT, folder, "package.json"),
  ).json();
  const { name, version, license } = manifestFields(manifest, folder);
  if (!ALLOWED_LICENSES.has(license)) {
    throw new Error(
      `${name} is licensed ${license}, outside ${[...ALLOWED_LICENSES].join(", ")}. Fix: check that its terms allow bundling, then add the license to ALLOWED_LICENSES.`,
    );
  }

  const files = await readdir(join(ROOT, folder));
  const licenseFile = files.find((file) => /^licen[cs]e(\..+)?$/i.test(file));
  if (licenseFile === undefined) {
    throw new Error(`${name} ships no LICENSE file to copy its notice from.`);
  }
  const text = await Bun.file(join(ROOT, folder, licenseFile)).text();

  return `${name}@${version} (${license})\n\n${text.trim()}\n`;
}

function manifestFields(
  manifest: unknown,
  folder: string,
): { name: string; version: string; license: string } {
  const field = (key: string): string => {
    const value: unknown =
      typeof manifest === "object" && manifest !== null
        ? Reflect.get(manifest, key)
        : undefined;
    if (typeof value !== "string") {
      throw new Error(`${folder}/package.json has no string "${key}".`);
    }
    return value;
  };

  return {
    name: field("name"),
    version: field("version"),
    license: field("license"),
  };
}

if (import.meta.main) {
  const { values } = parseArgs({ options: { check: { type: "boolean" } } });
  const built = await buildMarkdown();
  const files = [
    [OUTPUT_PATH, built.bundle],
    [LICENSES_PATH, built.licenses],
  ] as const;

  const stale = await Promise.all(
    files.map(async ([path, content]) => {
      if (!values.check) {
        await Bun.write(join(ROOT, path), content);
        console.log(`wrote ${path}`);
        return false;
      }

      const committed = await Bun.file(join(ROOT, path))
        .text()
        .catch(() => "");
      if (committed === content) return false;

      console.error(
        `${path} is stale. Fix: run \`bun run build:markdown\` and commit the result.`,
      );
      return true;
    }),
  );
  if (stale.includes(true)) process.exitCode = 1;
}
